"""Writes docs/art-evidence/MAP_ART_INDEX.md from the registry + a semantic-name -> registry-prop table."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
reg = json.loads((ROOT / 'src/data/artRegistry.generated.json').read_text(encoding='utf8'))
SEM = ['tree', 'rock', 'boulder', 'rubble', 'crate', 'lamp', 'bench', 'car', 'building_a', 'building_b', 'building_big', 'house',
       'fountain', 'timemachine', 'ship', 'pod', 'machine', 'pillar', 'lab_building', 'capsule_dome', 'palace', 'pavilion', 'tent',
       'stall', 'stand', 'plant']
M = {
    'landing_future': dict(tree='tree', rock='rock', boulder='rock_big', rubble='rock_pile', crate='chest_steel', pillar='ruin_pillar', plant='bush', pod='crater', timemachine='crater'),
    'capsule_corp': dict(tree='tree', rock='planter', boulder='dome_blue', crate='crate', lamp='lamp', bench='bench', car='hovercar', building_a='tower', building_b='hall_yellow', building_big='main_building', house='dome_house', fountain='fountain', ship='landing_pad', pod='capsule_tube', machine='terminal', pillar='pylon', lab_building='door_building', capsule_dome='dome_house', plant='planter', timemachine='landing_pad', stall='gate'),
    'south_city': dict(tree='tree_tall', rock='rubble', boulder='rubble_b', rubble='rubble', crate='crate', lamp='lamp', bench='bench', car='car_red', building_a='shop_grey', building_b='shop_green', building_big='shop_blue', house='shop_red', stall='vending_red', stand='bus_stop', pod='hover_pod', machine='vending_blue', pillar='lamp_b', plant='hedge', ship='hover_pod', timemachine='hover_pod'),
    'rocky_outskirts': dict(tree='dead_tree', rock='rock', boulder='rock_b', rubble='ruins', crate='chest', lamp='pillar_b', pillar='pillar_ruin', house='dome_hut', capsule_dome='dome_hut', plant='bush', pod='silo_small', machine='silo', timemachine='silo', ship='silo', building_a='tower_rock', building_big='ruin_ring', pavilion='ruin_ring'),
    'mountain_lab': dict(tree='pine_snow', rock='rock', boulder='rock_b', rubble='vent', crate='crate_green', lamp='beacon', machine='machine', pillar='radio_tower', lab_building='lab_gate', building_big='lab_gate_cliff', building_a='lab_gate_open', plant='bush', pod='console', stand='platform', stall='terminal'),
    'lab_inner': dict(crate='crate_green', lamp='tube_dark', machine='computer', pillar='tube_red', pod='pod_purple', lab_building='wall_door', building_a='wall_terminal', building_b='elevator_door', building_big='platform', stand='platform_stairs', ship='android_pod', timemachine='android_pod', stall='table_parts', rubble='table_parts_b', boulder='cart', rock='canister', plant='server', tree='server_tall', bench='console_chair', fountain='pod_pair'),
    'gingertown': dict(tree='tree', rock='rock', boulder='ruin', rubble='wall_ruin', crate='trashcan', lamp='lamp', bench='fence', car='car_beige', building_a='house_small', building_b='house_green', building_big='ruin', house='house_red', capsule_dome='dome_pink', plant='bush', pillar='cypress', stall='billboard', pod='dome_white', stand='billboard', machine='mailbox_red'),
    'android_island': dict(tree='palm', rock='rock', boulder='boulders', rubble='pillars_broken', crate='crate', lamp='stone_pillar', pillar='pillar_ruin', pod='cell_pod', machine='terminal', building_big='cliff_big', building_a='bunker_wall', building_b='bunker_wall_b', lab_building='tunnel_door', plant='bush', ship='cell_pod', timemachine='cell_pod', stall='console'),
    'lookout': dict(tree='cypress', plant='cypress_pot', pillar='column_a', palace='palace', pavilion='pavilion', building_big='palace', building_a='palace_tower', fountain='fountain_pad', bench='balustrade', stand='stairs', machine='hourglass_shrine', pod='platform_oval', rock='pot_round', crate='pot_tall', lamp='column_d'),
    'time_chamber': dict(pavilion='pavilion_exit', pillar='pillar_a', pod='orb', machine='hourglass', building_a='arch_wall', building_b='arch_door', building_big='arch_tall', stand='floor_oval', lamp='pillar_c', fountain='pad_large'),
    'cell_games_approach': dict(tree='tree', rock='rock', boulder='rock_c', rubble='rubble', crate='crate_steel', lamp='light_tower', bench='barrier', car='jeep', building_big='tent_white', building_a='tent_blue', building_b='stage_small', stall='tent_blue', stand='stage_small', tent='tent_white', pillar='obelisk', machine='truss', pod='capsule_car', ship='truck', house='van', plant='cypress', fountain='rope_posts'),
    'cell_games_arena': dict(tree='tree', rock='rock', boulder='crater_ring', rubble='rubble', crate='crate_steel', lamp='obelisk_c', bench='barrier', building_big='stage', building_a='stands', building_b='stands_corner', stand='stands', stall='announcer_stage', pillar='obelisk', plant='cypress', pavilion='announcer_stage', tent='announcer_stage', machine='gate_wall'),
}
L = ['# MAP ART INDEX', '',
     'Generated by tools/art_map_index.py from src/data/artRegistry.generated.json. Paths are relative to the site root (public/).',
     'tileSize = 32. Tile classes: floor, floor2, path, wall, water, edge (file: assets/worlds/<map>/tiles/<class>.png).',
     'Props: assets/worlds/<map>/props/<name>.png, anchored bottom-centre. foot = tiles occupied at the prop bottom; solid = block movement.',
     'Prop art is stored at 1/2 source scale. Backdrops (opaque, battle only): assets/worlds/<map>/backdrop-*.png.',
     'Shared source sheets (documented reuse): lookout + time_chamber, cell_games_approach + cell_games_arena.',
     'Tiles with quality procedural_fallback: all `water` tiles for south_city, mountain_lab, lab_inner, lookout, cell_games_*; all other tiles are derived (cross-blended seamless patches).',
     'Semantic names with no good match on a map are marked (none); the map should skip them or pick any prop from the full list.', '']
bad = []
for mid, w in reg['worlds'].items():
    L += [f'## {mid}', '', w['note'], '', 'Backdrops: ' + ', '.join(Path(b['path']).stem for b in w['backdrops']), '',
          'Tiles: ' + ', '.join(w['tiles']), '', '### Semantic name -> prop', '', '| semantic | prop | size | foot | solid |', '|---|---|---|---|---|']
    for s in SEM:
        n = M[mid].get(s)
        if n is None:
            L.append(f'| {s} | (none) | | | |')
            continue
        pr = w['props'].get(n)
        if not pr:
            bad.append((mid, s, n))
            continue
        L.append(f'| {s} | `{n}` | {pr["w"]}x{pr["h"]} | {pr["footW"]}x{pr["footH"]} | {"yes" if pr["solid"] else "no"} |')
    L += ['', '### All props', '', '| prop | size | foot | solid |', '|---|---|---|---|']
    for n, pr in w['props'].items():
        L.append(f'| `{n}` | {pr["w"]}x{pr["h"]} | {pr["footW"]}x{pr["footH"]} | {"yes" if pr["solid"] else "no"} |')
    L.append('')
(ROOT / 'docs/art-evidence/MAP_ART_INDEX.md').write_text('\n'.join(L), encoding='utf8')
print('bad mappings:', bad)
